-- Run in the existing project's Supabase SQL editor as the project administrator.
-- Additive backend-only RPC migration; no game/session records are deleted.
-- Generated by backend/scripts/export_http_migration.py. Contains no credentials.
BEGIN;
SET LOCAL statement_timeout = '60s';
DO $$ DECLARE current_revision text; BEGIN
 SELECT version_num INTO current_revision FROM twitch_games.alembic_version FOR UPDATE;
 IF current_revision IS DISTINCT FROM '0004_dashboard_auth' THEN
  RAISE EXCEPTION 'Expected revision 0004_dashboard_auth; got %.',current_revision;
 END IF;
END $$;
-- Backend-only HTTPS RPCs. Private tables remain outside the exposed schema.
CREATE TABLE twitch_games.backend_claims (
 kind text NOT NULL, key text NOT NULL, lease uuid NOT NULL,
 expires_at timestamptz NOT NULL, context jsonb NOT NULL DEFAULT '{}',
 PRIMARY KEY(kind,key)
);
ALTER TABLE twitch_games.backend_claims ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON twitch_games.backend_claims FROM PUBLIC;

CREATE FUNCTION twitch_games.rpc_fail(code text, message text, status integer DEFAULT 409)
RETURNS void LANGUAGE plpgsql SET search_path='' AS $$
BEGIN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE=code,
 DETAIL=jsonb_build_object('message',message,'status',status)::text; END $$;

CREATE FUNCTION twitch_games.rpc_permission(actor jsonb, channel text, permission text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
DECLARE grants jsonb;
BEGIN
 IF actor->>'channel_id' IS DISTINCT FROM channel THEN
  PERFORM twitch_games.rpc_fail('forbidden','Credential belongs to another channel',403);
 END IF;
 IF actor->>'role'='broadcaster' AND (actor->>'user_id' IS NULL OR actor->>'user_id'=channel) THEN
  RETURN '["live_control","question_review","settings"]'::jsonb;
 END IF;
 SELECT coalesce(jsonb_agg(g.permission ORDER BY g.permission),'[]') INTO grants
 FROM twitch_games.moderator_grants g WHERE g.channel_id=channel AND g.moderator_twitch_id=actor->>'user_id';
 IF grants='[]'::jsonb OR (permission IS NOT NULL AND NOT grants ? permission) THEN
  PERFORM twitch_games.rpc_fail('forbidden','This workspace permission has not been granted',403);
 END IF;
 RETURN grants;
END $$;

CREATE FUNCTION twitch_games.rpc_state(channel text) RETURNS jsonb
LANGUAGE plpgsql SET search_path='' AS $$
DECLARE game twitch_games.game_sessions; r twitch_games.rounds; value jsonb; v bigint;
BEGIN
 SELECT version INTO v FROM twitch_games.channels WHERE id=channel;
 SELECT * INTO game FROM twitch_games.game_sessions WHERE channel_id=channel ORDER BY created_at DESC,id DESC LIMIT 1;
 value=jsonb_build_object('channel_id',channel,'game_id',game.id,'status',coalesce(game.status,'idle'),
 'version',coalesce(v,0),'server_time',clock_timestamp(),'round',NULL);
 IF game.id IS NOT NULL THEN
  SELECT * INTO r FROM twitch_games.rounds WHERE game_id=game.id ORDER BY created_at DESC,id DESC LIMIT 1;
  IF r.id IS NOT NULL THEN
   value=value||jsonb_build_object('round',jsonb_build_object('round_id',r.id,'phase',r.phase,'prompt',r.prompt_snapshot)||
    CASE WHEN r.phase='results' THEN jsonb_build_object('complete_quote',r.complete_quote_snapshot,'canonical_answer',r.canonical_answer_snapshot)
    ELSE jsonb_build_object('opened_at',r.opened_at,'closes_at',r.closes_at) END);
  END IF;
 END IF;
 RETURN value;
END $$;

CREATE FUNCTION twitch_games.rpc_bump(channel text) RETURNS void
LANGUAGE plpgsql SET search_path='' AS $$
DECLARE v bigint;
BEGIN
 UPDATE twitch_games.channels SET version=version+1 WHERE id=channel RETURNING version INTO v;
 UPDATE twitch_games.game_sessions SET version=v WHERE channel_id=channel AND status='active';
 INSERT INTO twitch_games.state_notifications(channel_id,version) VALUES(channel,v)
 ON CONFLICT(channel_id) DO UPDATE SET version=excluded.version;
END $$;

CREATE FUNCTION twitch_games.rpc_candidates(stream uuid) RETURNS jsonb
LANGUAGE sql SET search_path='' AS $$
 SELECT coalesce(jsonb_agg(row_to_json(x)),'[]') FROM (
 SELECT q.id AS question_id,q.complete_quote,q.prompt,q.canonical_answer,q.accepted_aliases,
 jsonb_build_object('stream_id',q.stream_id,'segment_ids',jsonb_agg(s.id ORDER BY s.observed_at,s.sequence),'received_at',max(s.received_at)) AS source
 FROM twitch_games.question_candidates q JOIN twitch_games.question_sources qs ON qs.question_id=q.id
 JOIN twitch_games.transcript_segments s ON s.id=qs.segment_id
 WHERE q.stream_id=stream AND q.review_status='approved' AND NOT EXISTS(SELECT 1 FROM twitch_games.rounds r WHERE r.question_id=q.id)
 GROUP BY q.id ORDER BY q.selection_weight DESC,q.created_at,q.id LIMIT 50) x
$$;

CREATE FUNCTION twitch_games.rpc_board(game uuid, channel text, viewer text) RETURNS jsonb
LANGUAGE plpgsql SET search_path='' AS $$
DECLARE result jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM twitch_games.game_sessions WHERE id=game AND channel_id=channel) THEN
  PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404);
 END IF;
 WITH totals AS (SELECT participant_id,sum(points)::int AS points FROM twitch_games.score_entries WHERE game_id=game GROUP BY participant_id),
 ranked AS (SELECT participant_id,points,rank() OVER(ORDER BY points DESC) AS rank,row_number() OVER(ORDER BY points DESC,participant_id) AS position FROM totals),
 entries AS (SELECT r.*,coalesce(p.display_name,'Viewer '||r.participant_id) AS display_name FROM ranked r JOIN twitch_games.participants p ON p.id=r.participant_id)
 SELECT jsonb_build_object('game_id',game,'version',(SELECT version FROM twitch_games.channels WHERE id=channel),
 'final',(SELECT status='ended' FROM twitch_games.game_sessions WHERE id=game),
 'entries',coalesce((SELECT jsonb_agg(to_jsonb(e)-'position' ORDER BY position) FROM entries e WHERE position<=100),'[]'),
 'own_entry',(SELECT to_jsonb(e)-'position' FROM entries e WHERE participant_id=viewer)) INTO result;
 RETURN result;
END $$;

CREATE FUNCTION twitch_games.rpc_profile(profile jsonb) RETURNS void
LANGUAGE sql SET search_path='' AS $$
 INSERT INTO twitch_games.twitch_users(id,login,display_name,profile_image_url)
 VALUES(profile->>'id',profile->>'login',profile->>'display_name',profile->>'profile_image_url')
 ON CONFLICT(id) DO UPDATE SET login=excluded.login,display_name=excluded.display_name,
 profile_image_url=excluded.profile_image_url,updated_at=clock_timestamp()
$$;

CREATE TABLE twitch_games.generation_queue (
 stream_id uuid PRIMARY KEY REFERENCES twitch_games.streams(id), channel_id varchar(32) NOT NULL REFERENCES twitch_games.channels(id),
 requested_version bigint NOT NULL DEFAULT 0, processed_version bigint NOT NULL DEFAULT -1
);
ALTER TABLE twitch_games.generation_queue ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON twitch_games.generation_queue FROM PUBLIC;
CREATE FUNCTION twitch_games.rpc_score(round_uuid uuid, awards jsonb) RETURNS boolean
LANGUAGE plpgsql SET search_path='' AS $$
DECLARE r twitch_games.rounds; item jsonb; actual_count bigint; supplied_count bigint;
BEGIN
 SELECT * INTO r FROM twitch_games.rounds WHERE id=round_uuid FOR UPDATE;
 IF r.id IS NULL OR r.phase='results' THEN RETURN false; END IF;
 IF r.phase<>'answering' OR clock_timestamp()<r.closes_at THEN PERFORM twitch_games.rpc_fail('round_active','The 30-second answer window has not ended'); END IF;
 SELECT count(DISTINCT participant_id) INTO actual_count FROM twitch_games.submissions WHERE round_id=r.id;
 SELECT count(DISTINCT value->>'participant_id') INTO supplied_count FROM jsonb_array_elements(awards);
 IF actual_count<>supplied_count OR actual_count<>jsonb_array_length(awards) THEN PERFORM twitch_games.rpc_fail('stale_state','Scoring input does not match closed submissions'); END IF;
 FOR item IN SELECT * FROM jsonb_array_elements(awards) LOOP
  IF NOT EXISTS(SELECT 1 FROM twitch_games.submissions s WHERE s.id=(item->>'submission_id')::uuid AND s.round_id=r.id AND s.participant_id=item->>'participant_id'
    AND s.revision=(SELECT max(revision) FROM twitch_games.submissions WHERE round_id=r.id AND participant_id=s.participant_id)) THEN
   PERFORM twitch_games.rpc_fail('stale_state','Scoring input is stale');
  END IF;
  INSERT INTO twitch_games.score_entries(submission_id,round_id,game_id,channel_id,participant_id,outcome,points,scoring_policy_id)
   VALUES((item->>'submission_id')::uuid,r.id,r.game_id,r.channel_id,item->>'participant_id',
    CASE WHEN (item->>'correct')::boolean THEN 'correct' ELSE 'incorrect' END,CASE WHEN (item->>'correct')::boolean THEN 1 ELSE 0 END,r.scoring_policy_id)
   ON CONFLICT(round_id,participant_id) DO NOTHING;
 END LOOP;
 UPDATE twitch_games.rounds SET phase='results',closed_at=clock_timestamp(),version=version+1 WHERE id=r.id;
 RETURN true;
END $$;

CREATE FUNCTION public.twitch_games_backend(operation text, args jsonb DEFAULT '{}') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor jsonb=args->'actor'; channel text=actor->>'channel_id'; uid text=actor->>'user_id';
 permissions jsonb; value jsonb; profile jsonb; rowdata jsonb; v bigint; target uuid;
 game twitch_games.game_sessions; r twitch_games.rounds; s twitch_games.streams;
 q twitch_games.question_candidates; receipt twitch_games.command_receipts;
 submission twitch_games.submissions; auth twitch_games.oauth_authorizations;
 item twitch_games.state_notifications; claim twitch_games.backend_claims;
 now_at timestamptz=clock_timestamp(); token uuid; segment jsonb; candidate jsonb; entry jsonb;
 received timestamptz; key_text text; last_received timestamptz;
BEGIN
 IF operation='health' THEN
  RETURN jsonb_build_object('revision',(SELECT version_num FROM twitch_games.alembic_version),'transport','supabase_http');
 ELSIF operation='oauth_state_new' THEN
  INSERT INTO twitch_games.oauth_states(digest,expires_at) VALUES(args->>'digest',now_at+interval '10 minutes'); RETURN 'null';
 ELSIF operation='oauth_state_consume' THEN
  DELETE FROM twitch_games.oauth_states WHERE digest=args->>'digest' AND expires_at>now_at RETURNING to_jsonb(digest) INTO value;
  RETURN coalesce(value,'null');
 ELSIF operation='oauth_login' THEN
  profile=args->'profile'; PERFORM twitch_games.rpc_profile(profile);
  INSERT INTO twitch_games.channels(id,display_name) VALUES(profile->>'id',profile->>'display_name')
   ON CONFLICT(id) DO UPDATE SET display_name=excluded.display_name;
  INSERT INTO twitch_games.oauth_authorizations(user_id,encrypted_access_token,encrypted_refresh_token,access_expires_at,validated_at)
   VALUES(profile->>'id',args->>'access',args->>'refresh',now_at+make_interval(secs=>(args->>'seconds')::int),now_at)
   ON CONFLICT(user_id) DO UPDATE SET encrypted_access_token=excluded.encrypted_access_token,
   encrypted_refresh_token=excluded.encrypted_refresh_token,access_expires_at=excluded.access_expires_at,validated_at=excluded.validated_at,revoked_at=NULL;
  DELETE FROM twitch_games.backend_claims WHERE kind='auth' AND key=profile->>'id';
  DELETE FROM twitch_games.dashboard_sessions WHERE digest=args->>'old_digest';
  INSERT INTO twitch_games.dashboard_sessions(digest,user_id,expires_at) VALUES(args->>'session_digest',profile->>'id',now_at+interval '24 hours'); RETURN 'null';
 ELSIF operation='session_read' THEN
  SELECT to_jsonb(t) INTO value FROM twitch_games.dashboard_sessions t WHERE digest=args->>'digest' AND expires_at>now_at;
  RETURN coalesce(value,'null');
 ELSIF operation='logout' THEN
  DELETE FROM twitch_games.dashboard_sessions WHERE digest=args->>'digest'; RETURN 'null';
 ELSIF operation='auth_claim' THEN
  SELECT * INTO auth FROM twitch_games.oauth_authorizations WHERE user_id=args->>'user_id' FOR UPDATE;
  IF auth.user_id IS NULL OR auth.revoked_at IS NOT NULL THEN RETURN jsonb_build_object('status','revoked'); END IF;
  IF NOT coalesce((args->>'force')::boolean,false) AND auth.access_expires_at>now_at AND auth.validated_at>now_at-interval '1 hour' THEN
   RETURN jsonb_build_object('status','valid');
  END IF;
  SELECT * INTO claim FROM twitch_games.backend_claims WHERE kind='auth' AND key=auth.user_id;
  IF claim.expires_at>now_at THEN PERFORM twitch_games.rpc_fail('database_unavailable','Twitch authorization is being refreshed; retry shortly',503); END IF;
  token=gen_random_uuid();
  INSERT INTO twitch_games.backend_claims(kind,key,lease,expires_at,context)
   VALUES('auth',auth.user_id,token,now_at+interval '30 seconds',jsonb_build_object('access',auth.encrypted_access_token))
   ON CONFLICT(kind,key) DO UPDATE SET lease=excluded.lease,expires_at=excluded.expires_at,context=excluded.context;
  RETURN jsonb_build_object('status','claimed','lease',token,'record',to_jsonb(auth));
 ELSIF operation='auth_finish' THEN
  SELECT * INTO auth FROM twitch_games.oauth_authorizations WHERE user_id=args->>'user_id' FOR UPDATE;
  SELECT * INTO claim FROM twitch_games.backend_claims WHERE kind='auth' AND key=args->>'user_id' FOR UPDATE;
  IF claim.lease IS DISTINCT FROM (args->>'lease')::uuid OR claim.expires_at<=now_at OR claim.context->>'access' IS DISTINCT FROM auth.encrypted_access_token THEN
   PERFORM twitch_games.rpc_fail('database_unavailable','Authorization changed during refresh; retry',503);
  END IF;
  IF coalesce((args->>'revoke')::boolean,false) THEN
   UPDATE twitch_games.oauth_authorizations SET revoked_at=now_at WHERE user_id=auth.user_id;
   DELETE FROM twitch_games.dashboard_sessions WHERE user_id=auth.user_id;
  ELSIF args ? 'access' THEN
   UPDATE twitch_games.oauth_authorizations SET encrypted_access_token=args->>'access',encrypted_refresh_token=args->>'refresh',
    access_expires_at=now_at+make_interval(secs=>(args->>'seconds')::int),validated_at=now_at WHERE user_id=auth.user_id;
  END IF;
  DELETE FROM twitch_games.backend_claims WHERE kind='auth' AND key=auth.user_id; RETURN 'null';
 ELSIF operation='auth_due' THEN
  DELETE FROM twitch_games.oauth_states WHERE expires_at<=now_at;
  DELETE FROM twitch_games.dashboard_sessions WHERE expires_at<=now_at;
  IF coalesce((args->>'startup')::boolean,false) THEN UPDATE twitch_games.oauth_authorizations SET validated_at='epoch' WHERE revoked_at IS NULL; END IF;
  SELECT coalesce(jsonb_agg(user_id),'[]') INTO value FROM (SELECT user_id FROM twitch_games.oauth_authorizations WHERE revoked_at IS NULL AND user_id>coalesce(args->>'after','') AND
   (validated_at<=now_at-interval '1 hour' OR access_expires_at<=now_at) ORDER BY user_id LIMIT 100) x; RETURN value;
 ELSIF operation='permissions' THEN RETURN twitch_games.rpc_permission(actor,channel,args->>'permission');
 ELSIF operation='identity' THEN
  permissions=twitch_games.rpc_permission(actor,channel);
  SELECT jsonb_build_object('user_id',id,'login',login,'display_name',display_name,'avatar_url',profile_image_url) INTO profile FROM twitch_games.twitch_users WHERE id=uid;
  SELECT coalesce(jsonb_agg(x),'[]') INTO value FROM (
   SELECT c.id AS channel_id,c.display_name,u.login,'owner'::text AS role,'["live_control","question_review","settings"]'::jsonb AS permissions
    FROM twitch_games.channels c JOIN twitch_games.twitch_users u ON u.id=c.id WHERE c.id=uid
   UNION ALL SELECT g.channel_id,c.display_name,u.login,'moderator',jsonb_agg(g.permission ORDER BY g.permission)
    FROM twitch_games.moderator_grants g JOIN twitch_games.channels c ON c.id=g.channel_id
    JOIN twitch_games.twitch_users u ON u.id=g.channel_id WHERE g.moderator_twitch_id=uid GROUP BY g.channel_id,c.display_name,u.login) x;
  RETURN jsonb_build_object('user',profile,'owned_channel',(SELECT jsonb_build_object('channel_id',id,'display_name',display_name) FROM twitch_games.channels WHERE id=uid),
   'workspaces',value,'selected_workspace',jsonb_build_object('channel_id',channel,'role',CASE WHEN uid=channel THEN 'owner' ELSE 'moderator' END,'permissions',permissions));
 ELSIF operation='command_receipt' THEN
  PERFORM twitch_games.rpc_permission(actor,channel,'live_control');
  SELECT * INTO receipt FROM twitch_games.command_receipts WHERE channel_id=channel AND request_id=(args->'body'->>'request_id')::uuid;
  IF receipt.request_id IS NOT NULL AND receipt.digest IS DISTINCT FROM args->>'digest' THEN PERFORM twitch_games.rpc_fail('request_conflict','Request ID was already used for another command'); END IF;
  RETURN coalesce(receipt.response,'null');
 ELSIF operation='open_input' THEN
  PERFORM twitch_games.rpc_permission(actor,channel,'live_control');
  SELECT * INTO game FROM twitch_games.game_sessions WHERE id=(args->>'game_id')::uuid AND channel_id=channel;
  IF game.id IS NULL THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404); END IF;
  SELECT * INTO q FROM twitch_games.question_candidates t WHERE t.stream_id=game.stream_id AND t.review_status='approved'
    AND ((args->>'question_id') IS NULL OR t.id=(args->>'question_id')::uuid)
    AND NOT EXISTS(SELECT 1 FROM twitch_games.rounds WHERE question_id=t.id) ORDER BY t.selection_weight DESC,t.created_at,t.id LIMIT 1;
  IF q.id IS NULL THEN PERFORM twitch_games.rpc_fail('transcript_unavailable','Waiting for a new usable quote from this stream'); END IF;
  RETURN to_jsonb(q);
 ELSIF operation='resolve' THEN
  CASE args->>'kind'
   WHEN 'game_id' THEN SELECT channel_id INTO key_text FROM twitch_games.game_sessions WHERE id=(args->>'id')::uuid;
   WHEN 'round_id' THEN SELECT channel_id INTO key_text FROM twitch_games.rounds WHERE id=(args->>'id')::uuid;
   WHEN 'stream_id' THEN SELECT channel_id INTO key_text FROM twitch_games.streams WHERE id=(args->>'id')::uuid;
   ELSE PERFORM twitch_games.rpc_fail('not_found','Resource not found',404);
  END CASE;
  IF key_text IS NULL THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found',404); END IF;
  RETURN to_jsonb(key_text);
 END IF;
 -- All remaining public operations are explicitly handled below. There is no SQL text parameter.
 IF operation='state' THEN
  PERFORM 1 FROM twitch_games.channels WHERE id=channel FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('channel_id',channel,'game_id',NULL,'status','idle','version',0,'server_time',clock_timestamp(),'round',NULL); END IF;
  IF actor->>'source'='dashboard' THEN PERFORM twitch_games.rpc_permission(actor,channel); END IF;
  RETURN twitch_games.rpc_state(channel);
 ELSIF operation='board' THEN
  PERFORM 1 FROM twitch_games.channels WHERE id=channel FOR SHARE;
  IF actor->>'source'='dashboard' THEN PERFORM twitch_games.rpc_permission(actor,channel); END IF;
  RETURN twitch_games.rpc_board((args->>'game_id')::uuid,channel,uid);
 ELSIF operation='own' THEN
  SELECT * INTO r FROM twitch_games.rounds WHERE id=(args->>'round_id')::uuid AND channel_id=channel FOR SHARE;
  IF r.id IS NULL THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404); END IF;
  SELECT * INTO submission FROM twitch_games.submissions WHERE round_id=r.id AND participant_id=uid ORDER BY revision DESC LIMIT 1;
  value=jsonb_build_object('round_id',r.id,'answer',submission.raw_answer,'receipt',
   CASE WHEN submission.id IS NULL THEN NULL ELSE jsonb_build_object('submission_id',submission.id,'round_id',r.id,'request_id',submission.request_id,'received_at',submission.received_at,'status','received') END,'result',NULL);
  IF r.phase='results' THEN
   SELECT jsonb_build_object('round_id',round_id,'submission_id',submission_id,'outcome',outcome,'awarded_points',points,'scoring_policy_id',scoring_policy_id)
    INTO rowdata FROM twitch_games.score_entries WHERE round_id=r.id AND participant_id=uid;
   value=value||jsonb_build_object('result',rowdata);
  END IF; RETURN value;
 ELSIF operation='dashboard' THEN
  PERFORM 1 FROM twitch_games.channels WHERE id=channel FOR SHARE;
  permissions=twitch_games.rpc_permission(actor,channel);
  SELECT * INTO s FROM twitch_games.streams WHERE channel_id=channel AND ended_at IS NULL ORDER BY created_at DESC LIMIT 1;
  SELECT max(received_at) INTO last_received FROM twitch_games.transcript_segments WHERE stream_id=s.id;
  value=twitch_games.rpc_state(channel);
  RETURN jsonb_build_object('channel_id',channel,'stream_id',s.id,'game',value,
   'submission_count',(SELECT count(DISTINCT participant_id) FROM twitch_games.submissions WHERE round_id=(value->'round'->>'round_id')::uuid),
   'transcript',jsonb_build_object('last_received_at',last_received,'status',CASE WHEN s.id IS NULL THEN 'not_connected' WHEN last_received IS NULL THEN 'waiting' WHEN last_received>=now_at-interval '30 seconds' THEN 'receiving' ELSE 'stale' END),
   'candidates',CASE WHEN permissions ? 'question_review' AND s.id IS NOT NULL THEN twitch_games.rpc_candidates(s.id) ELSE '[]'::jsonb END);
 ELSIF operation='questions' THEN
  PERFORM twitch_games.rpc_permission(actor,channel,'question_review');
  IF NOT EXISTS(SELECT 1 FROM twitch_games.streams WHERE id=(args->>'stream_id')::uuid AND channel_id=channel) THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404); END IF;
  RETURN twitch_games.rpc_candidates((args->>'stream_id')::uuid);
 ELSIF operation='resource_check' THEN
  IF NOT EXISTS(SELECT 1 FROM twitch_games.rounds WHERE id=(args->>'round_id')::uuid AND channel_id=channel) THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404); END IF;
  RETURN jsonb_build_object('participant_exists',EXISTS(SELECT 1 FROM twitch_games.participants WHERE id=uid));
 ELSIF operation='submit' THEN
  SELECT * INTO r FROM twitch_games.rounds WHERE id=(args->>'round_id')::uuid AND channel_id=channel FOR UPDATE;
  IF r.id IS NULL THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404); END IF;
  SELECT * INTO submission FROM twitch_games.submissions WHERE round_id=r.id AND participant_id=uid AND request_id=(args->'body'->>'request_id')::uuid;
  IF submission.id IS NOT NULL THEN
   IF submission.raw_answer IS DISTINCT FROM args->'body'->>'answer' THEN PERFORM twitch_games.rpc_fail('request_conflict','Use a new request ID when editing an answer'); END IF;
  ELSE
   now_at=clock_timestamp();
   IF r.phase<>'answering' OR now_at>=r.closes_at THEN PERFORM twitch_games.rpc_fail('round_closed','This round no longer accepts answers'); END IF;
   INSERT INTO twitch_games.participants(id,display_name) VALUES(uid,args->>'display_name') ON CONFLICT DO NOTHING;
   INSERT INTO twitch_games.submissions(round_id,game_id,channel_id,participant_id,request_id,raw_answer,received_at)
    VALUES(r.id,r.game_id,channel,uid,(args->'body'->>'request_id')::uuid,args->'body'->>'answer',now_at) RETURNING * INTO submission;
  END IF;
  RETURN jsonb_build_object('submission_id',submission.id,'round_id',r.id,'request_id',submission.request_id,'received_at',submission.received_at,'status','received');
 ELSIF operation='generation_due' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') INTO value FROM (SELECT g.* FROM twitch_games.generation_queue g JOIN twitch_games.streams src ON src.id=g.stream_id WHERE g.processed_version<g.requested_version AND src.ended_at IS NULL ORDER BY g.stream_id LIMIT 5) t; RETURN value;
 ELSIF operation='generation_read' THEN
  SELECT * INTO s FROM twitch_games.streams WHERE id=(args->>'stream_id')::uuid AND ended_at IS NULL;
  IF s.id IS NULL THEN RETURN 'null'; END IF;
  RETURN jsonb_build_object('channel_id',s.channel_id,'version',(SELECT requested_version FROM twitch_games.generation_queue WHERE stream_id=s.id),
   'records',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT id,text FROM twitch_games.transcript_segments WHERE stream_id=s.id ORDER BY observed_at DESC,received_at DESC,sequence DESC,id DESC LIMIT 200) x),'[]'),
   'existing',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT canonical_answer,quote_digest FROM twitch_games.question_candidates WHERE stream_id=s.id ORDER BY created_at DESC LIMIT 2000) x),'[]'));
 ELSIF operation='generation_save' THEN
  SELECT * INTO s FROM twitch_games.streams WHERE id=(args->>'stream_id')::uuid FOR UPDATE;
  IF s.ended_at IS NOT NULL THEN RETURN 'null'; END IF;
  FOR candidate IN SELECT * FROM jsonb_array_elements(args->'candidates') LOOP
   SELECT string_agg(t.text,' ' ORDER BY ids.position),count(*) INTO key_text,v
    FROM jsonb_array_elements_text(candidate->'segment_ids') WITH ORDINALITY ids(id,position)
    JOIN twitch_games.transcript_segments t ON t.id=ids.id::uuid AND t.stream_id=s.id AND t.channel_id=s.channel_id;
   IF key_text IS DISTINCT FROM candidate->>'complete_quote' OR v<>jsonb_array_length(candidate->'segment_ids') THEN
    PERFORM twitch_games.rpc_fail('validation_error','Quote evidence does not match source text',422);
   END IF;
   INSERT INTO twitch_games.question_candidates(stream_id,channel_id,complete_quote,prompt,canonical_answer,quote_digest,blank_start,blank_end,accepted_aliases,review_status,generator_version,selection_weight)
    VALUES(s.id,s.channel_id,candidate->>'complete_quote',candidate->>'prompt',candidate->>'canonical_answer',candidate->>'digest',
     (candidate->>'blank_start')::int,(candidate->>'blank_end')::int,'[]','approved',args->>'generator',(candidate->>'weight')::float8)
    ON CONFLICT DO NOTHING RETURNING * INTO q;
   IF q.id IS NOT NULL THEN
    INSERT INTO twitch_games.question_sources(question_id,segment_id,stream_id,channel_id)
     SELECT q.id,e.value::uuid,s.id,s.channel_id FROM jsonb_array_elements_text(candidate->'segment_ids') e;
   END IF;
  END LOOP;
  UPDATE twitch_games.generation_queue SET processed_version=greatest(processed_version,(args->>'version')::bigint) WHERE stream_id=s.id;
  RETURN 'null';
 ELSIF operation='score_input' THEN
  SELECT * INTO r FROM twitch_games.rounds WHERE id=(args->>'round_id')::uuid;
  IF r.id IS NULL THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found',404); END IF;
  IF actor IS NOT NULL THEN
   PERFORM twitch_games.rpc_permission(actor,r.channel_id,'live_control');
   IF r.channel_id<>channel THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found',404); END IF;
  END IF;
  RETURN jsonb_build_object('round',to_jsonb(r),'submissions',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM
   (SELECT DISTINCT ON(participant_id) id,participant_id,raw_answer FROM twitch_games.submissions WHERE round_id=r.id ORDER BY participant_id,revision DESC) t),'[]'));
 ELSIF operation='score_due' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO value FROM (SELECT id,channel_id FROM twitch_games.rounds WHERE phase='answering' AND closes_at<=now_at ORDER BY closes_at LIMIT 100) x; RETURN value;
 ELSIF operation='score_finalize' THEN
  SELECT * INTO r FROM twitch_games.rounds WHERE id=(args->>'round_id')::uuid;
  PERFORM 1 FROM twitch_games.channels WHERE id=r.channel_id FOR UPDATE;
  IF twitch_games.rpc_score(r.id,args->'awards') THEN PERFORM twitch_games.rpc_bump(r.channel_id); END IF;
  RETURN 'null';
 ELSIF operation='notice_claim' THEN
  SELECT * INTO item FROM twitch_games.state_notifications n WHERE n.version>n.published_version AND n.next_attempt_at<=now_at AND
   NOT EXISTS(SELECT 1 FROM twitch_games.backend_claims c WHERE c.kind='notice' AND c.key=n.channel_id AND c.expires_at>now_at)
   ORDER BY next_attempt_at LIMIT 1 FOR UPDATE SKIP LOCKED;
  IF item.channel_id IS NULL THEN RETURN 'null'; END IF;
  token=gen_random_uuid();
  INSERT INTO twitch_games.backend_claims(kind,key,lease,expires_at) VALUES('notice',item.channel_id,token,now_at+interval '15 seconds')
   ON CONFLICT(kind,key) DO UPDATE SET lease=excluded.lease,expires_at=excluded.expires_at;
  RETURN to_jsonb(item)||jsonb_build_object('lease',token);
 ELSIF operation='notice_finish' THEN
  SELECT * INTO item FROM twitch_games.state_notifications WHERE channel_id=args->>'channel_id' FOR UPDATE;
  SELECT * INTO claim FROM twitch_games.backend_claims WHERE kind='notice' AND key=item.channel_id FOR UPDATE;
  IF claim.lease IS DISTINCT FROM (args->>'lease')::uuid OR claim.expires_at<=now_at THEN RETURN 'null'; END IF;
  IF coalesce((args->>'success')::boolean,false) THEN
   UPDATE twitch_games.state_notifications SET published_version=greatest(published_version,(args->>'version')::bigint),attempts=0,last_sent_at=now_at,next_attempt_at=now_at+interval '1 second' WHERE channel_id=item.channel_id;
  ELSE
   UPDATE twitch_games.state_notifications SET attempts=attempts+1,next_attempt_at=now_at+make_interval(secs=>least(60,power(2,least(attempts+1,6))::int)) WHERE channel_id=item.channel_id;
  END IF;
  DELETE FROM twitch_games.backend_claims WHERE kind='notice' AND key=item.channel_id; RETURN 'null';
 END IF;
 -- Channel mutations serialize with game commands and grant revocation.
 IF actor->>'role'='broadcaster' AND coalesce(uid,channel)=channel THEN INSERT INTO twitch_games.channels(id) VALUES(channel) ON CONFLICT DO NOTHING; END IF;
 SELECT version INTO v FROM twitch_games.channels WHERE id=channel FOR UPDATE;
 IF v IS NULL THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404); END IF;
 IF operation IN ('stream_connect','intake') THEN permissions=twitch_games.rpc_permission(actor,channel,'settings');
 ELSIF operation='aliases' THEN permissions=twitch_games.rpc_permission(actor,channel,'question_review');
 ELSIF operation IN ('grants_list','grants_set','grants_revoke') THEN
  IF actor->>'role'<>'broadcaster' OR uid IS DISTINCT FROM channel THEN PERFORM twitch_games.rpc_fail('forbidden','Only this channel owner may manage grants',403); END IF;
 ELSE permissions=twitch_games.rpc_permission(actor,channel,'live_control'); END IF;
 IF operation='stream_connect' THEN
  SELECT * INTO s FROM twitch_games.streams WHERE channel_id=channel AND ended_at IS NULL ORDER BY created_at DESC LIMIT 1;
  IF s.twitch_stream_id IS DISTINCT FROM args->>'twitch_stream_id' THEN
   IF EXISTS(SELECT 1 FROM twitch_games.game_sessions WHERE channel_id=channel AND status='active') THEN PERFORM twitch_games.rpc_fail('game_active','End the active game before changing streams'); END IF;
   UPDATE twitch_games.streams SET ended_at=now_at WHERE channel_id=channel AND ended_at IS NULL;
   INSERT INTO twitch_games.streams(channel_id,twitch_stream_id,started_at) VALUES(channel,args->>'twitch_stream_id',(args->>'started_at')::timestamptz)
    ON CONFLICT(channel_id,twitch_stream_id) DO UPDATE SET ended_at=NULL RETURNING * INTO s;
  END IF;
  RETURN jsonb_build_object('stream_id',s.id,'twitch_stream_id',s.twitch_stream_id);
 ELSIF operation='intake' THEN
  SELECT * INTO s FROM twitch_games.streams WHERE id=(args->>'stream_id')::uuid AND channel_id=channel;
  IF s.id IS NULL THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404); END IF;
  IF s.ended_at IS NOT NULL THEN PERFORM twitch_games.rpc_fail('stream_unavailable','Caption stream is no longer current'); END IF;
  SELECT to_jsonb(t) INTO rowdata FROM twitch_games.transcript_batches t WHERE id=(args->'body'->>'batch_id')::uuid;
  IF rowdata IS NOT NULL THEN
   IF rowdata->>'stream_id'<>s.id::text OR rowdata->>'payload_digest'<>args->>'digest' THEN PERFORM twitch_games.rpc_fail('request_conflict','Batch ID was already used with different content'); END IF;
   RETURN jsonb_build_object('batch_id',args->'body'->>'batch_id','status','duplicate');
  END IF;
  INSERT INTO twitch_games.transcript_batches(id,stream_id,channel_id,source,payload_digest) VALUES((args->'body'->>'batch_id')::uuid,s.id,channel,args->'body'->>'source',args->>'digest');
  FOR segment IN SELECT e.value FROM jsonb_array_elements(args->'body'->'segments') e ORDER BY (e.value->>'sequence')::bigint LOOP
   received=(segment->>'observed_at')::timestamptz;
   IF received>clock_timestamp()+interval '30 seconds' OR received<s.started_at-interval '60 seconds' THEN PERFORM twitch_games.rpc_fail('validation_error','Caption timestamps are outside this stream',422); END IF;
   INSERT INTO twitch_games.transcript_segments(batch_id,stream_id,channel_id,sequence,text,observed_at)
    VALUES((args->'body'->>'batch_id')::uuid,s.id,channel,(segment->>'sequence')::bigint,segment->>'text',received);
  END LOOP;
  INSERT INTO twitch_games.generation_queue(stream_id,channel_id,requested_version) VALUES(s.id,channel,1)
   ON CONFLICT(stream_id) DO UPDATE SET requested_version=twitch_games.generation_queue.requested_version+1;
  RETURN jsonb_build_object('batch_id',args->'body'->>'batch_id','status','received');
 ELSIF operation='aliases' THEN
  IF args ? 'body' THEN
   INSERT INTO twitch_games.answer_aliases(channel_id,canonical,aliases) VALUES(channel,args->'body'->>'canonical',args->'body'->'aliases')
    ON CONFLICT(channel_id,canonical) DO UPDATE SET aliases=excluded.aliases;
  END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO value FROM (SELECT canonical,aliases FROM twitch_games.answer_aliases WHERE channel_id=channel ORDER BY canonical LIMIT 1000) x; RETURN value;
 ELSIF operation='grants_list' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO value FROM (SELECT g.moderator_twitch_id AS user_id,u.login,u.display_name,jsonb_agg(g.permission ORDER BY g.permission) AS permissions
   FROM twitch_games.moderator_grants g JOIN twitch_games.twitch_users u ON u.id=g.moderator_twitch_id WHERE g.channel_id=channel GROUP BY g.moderator_twitch_id,u.login,u.display_name ORDER BY u.login) x; RETURN value;
 ELSIF operation='grants_set' THEN
  PERFORM twitch_games.rpc_profile(args->'owner'); PERFORM twitch_games.rpc_profile(args->'moderator');
  IF args->'moderator'->>'id'=channel THEN PERFORM twitch_games.rpc_fail('validation_error','The owner already has all permissions',422); END IF;
  DELETE FROM twitch_games.moderator_grants WHERE channel_id=channel AND moderator_twitch_id=args->'moderator'->>'id';
  INSERT INTO twitch_games.moderator_grants(channel_id,moderator_twitch_id,permission,granted_by)
   SELECT channel,args->'moderator'->>'id',e.value,channel FROM jsonb_array_elements_text(args->'permissions') e;
  RETURN jsonb_build_object('user_id',args->'moderator'->>'id','login',args->'moderator'->>'login','permissions',args->'permissions');
 ELSIF operation='grants_revoke' THEN
  DELETE FROM twitch_games.moderator_grants WHERE channel_id=channel AND moderator_twitch_id=args->>'moderator_id'; RETURN 'null';
 END IF;
 IF operation NOT IN ('start','open','close','end') THEN PERFORM twitch_games.rpc_fail('validation_error','Unknown backend operation',422); END IF;
 SELECT * INTO receipt FROM twitch_games.command_receipts WHERE channel_id=channel AND request_id=(args->'body'->>'request_id')::uuid;
 IF receipt.request_id IS NOT NULL THEN
  IF receipt.digest IS DISTINCT FROM args->>'digest' THEN PERFORM twitch_games.rpc_fail('request_conflict','Request ID was already used for another command'); END IF;
  RETURN receipt.response;
 END IF;
 IF args->'body' ? 'expected_version' AND v<>(args->'body'->>'expected_version')::bigint THEN PERFORM twitch_games.rpc_fail('stale_state','Refresh the current state before sending this command'); END IF;
 IF operation='start' THEN
  IF args->'body'->>'policy_id'<>'quote_v1' OR args->'body'->>'mode'<>'quote' THEN PERFORM twitch_games.rpc_fail('unsupported_policy','Use the quote_v1 scoring policy',422); END IF;
  IF EXISTS(SELECT 1 FROM twitch_games.game_sessions WHERE channel_id=channel AND status='active') THEN PERFORM twitch_games.rpc_fail('game_active','A game is already active'); END IF;
  SELECT * INTO s FROM twitch_games.streams WHERE channel_id=channel AND ended_at IS NULL ORDER BY created_at DESC LIMIT 1;
  IF s.id IS NULL THEN PERFORM twitch_games.rpc_fail('stream_unavailable','Connect the current live stream first'); END IF;
  INSERT INTO twitch_games.game_sessions(stream_id,channel_id,mode,status,policy_id,policy_snapshot,version,started_at)
   VALUES(s.id,channel,'quote','active','quote_v1',args->'policy',0,now_at);
 ELSIF operation='open' THEN
  SELECT * INTO game FROM twitch_games.game_sessions WHERE id=(args->>'target')::uuid AND channel_id=channel;
  IF game.id IS NULL THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404); END IF;
  IF game.status<>'active' THEN PERFORM twitch_games.rpc_fail('game_ended','This game is no longer active'); END IF;
  IF EXISTS(SELECT 1 FROM twitch_games.rounds WHERE game_id=game.id AND phase NOT IN ('results','cancelled')) THEN PERFORM twitch_games.rpc_fail('round_active','Wait for the current round to finish'); END IF;
  SELECT * INTO q FROM twitch_games.question_candidates t WHERE t.stream_id=game.stream_id AND t.review_status='approved'
   AND t.id=(args->>'selected_question')::uuid AND NOT EXISTS(SELECT 1 FROM twitch_games.rounds WHERE question_id=t.id);
  IF q.id IS NULL THEN PERFORM twitch_games.rpc_fail('transcript_unavailable','Waiting for a new usable quote from this stream'); END IF;
  SELECT coalesce(jsonb_agg(DISTINCT x.value),'[]') INTO value FROM jsonb_array_elements(q.accepted_aliases||coalesce((SELECT aliases FROM twitch_games.answer_aliases WHERE channel_id=channel AND canonical=args->>'alias_key'),'[]')) x;
  INSERT INTO twitch_games.rounds(game_id,stream_id,channel_id,question_id,phase,version,prompt_snapshot,canonical_answer_snapshot,accepted_aliases_snapshot,scoring_policy_id,policy_snapshot,complete_quote_snapshot,opened_at,closes_at)
   VALUES(game.id,game.stream_id,channel,q.id,'answering',0,q.prompt,q.canonical_answer,value,'quote_v1',args->'policy',q.complete_quote,clock_timestamp(),clock_timestamp()+interval '30 seconds');
 ELSIF operation='close' THEN
  SELECT * INTO r FROM twitch_games.rounds WHERE id=(args->>'target')::uuid AND channel_id=channel;
  IF r.id IS NULL THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404); END IF;
  PERFORM twitch_games.rpc_score(r.id,args->'awards');
 ELSIF operation='end' THEN
  SELECT * INTO game FROM twitch_games.game_sessions WHERE id=(args->>'target')::uuid AND channel_id=channel;
  IF game.id IS NULL THEN PERFORM twitch_games.rpc_fail('not_found','Resource not found in this channel',404); END IF;
  IF game.status<>'active' THEN PERFORM twitch_games.rpc_fail('game_ended','This game has already ended'); END IF;
  IF EXISTS(SELECT 1 FROM twitch_games.rounds WHERE game_id=game.id AND phase NOT IN ('results','cancelled')) THEN PERFORM twitch_games.rpc_fail('round_active','Wait for the current round results before ending the game'); END IF;
  UPDATE twitch_games.game_sessions SET status='ended',ended_at=now_at WHERE id=game.id;
 END IF;
 PERFORM twitch_games.rpc_bump(channel); value=twitch_games.rpc_state(channel);
 INSERT INTO twitch_games.command_receipts(channel_id,request_id,digest,response) VALUES(channel,(args->'body'->>'request_id')::uuid,args->>'digest',value);
 RETURN value;
END $$;

REVOKE ALL ON FUNCTION public.twitch_games_backend(text,jsonb) FROM PUBLIC;
DO $$ DECLARE r text; BEGIN
 FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN
   EXECUTE format('REVOKE ALL ON FUNCTION public.twitch_games_backend(text,jsonb) FROM %I',r);
   EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA twitch_games FROM %I',r);
   EXECUTE format('REVOKE ALL ON twitch_games.backend_claims,twitch_games.generation_queue FROM %I',r);
  END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN
  GRANT EXECUTE ON FUNCTION public.twitch_games_backend(text,jsonb) TO service_role;
 END IF;
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA twitch_games FROM PUBLIC;
NOTIFY pgrst, 'reload schema';

UPDATE twitch_games.alembic_version SET version_num='0005_http_rpc'
 WHERE version_num='0004_dashboard_auth';
COMMIT;
-- Verify without reading protected records:
SELECT public.twitch_games_backend('health','{}'::jsonb);
